/**
 * snippetCatalog — каталог с фильтрами
 */
require_once MODX_CORE_PATH . 'components/andromedda/andromedda.class.php';

$data = Andromedda::loadCatalog();
$categories = $data['categories'] ?? [];
$products = $data['products'] ?? [];

if (empty($products)) {
    return '<p class="text-muted">Каталог временно недоступен.</p>';
}

$gradeFilters = [
    ['slug' => 'top', 'label' => 'Высший сорт / Новые', 'matches' => ['top']],
    ['slug' => 'first', 'label' => '1 сорт', 'matches' => ['first']],
    ['slug' => 'second', 'label' => '2 сорт', 'matches' => ['second']],
    ['slug' => 'third', 'label' => '3 сорт / Облегченный', 'matches' => ['third', 'light']],
];

$minPrice = min(array_column($products, 'priceFrom'));

$html = '<div class="grid gap-6 lg:grid-cols-12 lg:gap-8" id="catalog-browser">';
$html .= '<div class="min-w-0 lg:col-span-3"><div class="lg:sticky lg:top-[calc(var(--header-h)+24px)]">';
$html .= '<button type="button" id="catalog-filters-toggle" class="flex w-full items-center justify-between gap-3 rounded-[var(--radius-card)] border border-paper-200 bg-paper-0 px-5 py-4 lg:hidden" aria-expanded="false">';
$html .= '<span class="text-[14px] font-semibold text-ink-900">Фильтры</span>';
$html .= '<span aria-hidden="true">▼</span></button>';
$html .= '<div id="catalog-filters" class="mt-3 hidden rounded-[var(--radius-card)] border border-paper-200 bg-paper-0 p-5 lg:mt-0 lg:block">';
$html .= '<h2 class="eyebrow text-muted">Фильтры</h2>';

$html .= '<div class="mt-6 flex flex-col gap-7">';
$html .= '<div><h3 class="text-[12px] font-semibold tracking-[0.1em] text-muted uppercase">Тип поддона</h3><div class="mt-3.5 flex flex-col gap-2.5">';
foreach ($categories as $category) {
    $html .= '<label class="flex cursor-pointer items-center gap-3 text-[14px] text-slate-ink">';
    $html .= '<input type="checkbox" class="catalog-filter-type" value="' . htmlspecialchars($category['slug']) . '" />';
    $html .= htmlspecialchars($category['shortName']) . '</label>';
}
$html .= '</div></div>';

$html .= '<div><h3 class="text-[12px] font-semibold tracking-[0.1em] text-muted uppercase">Сорт</h3><div class="mt-3.5 flex flex-col gap-2.5">';
foreach ($gradeFilters as $grade) {
    $html .= '<label class="flex cursor-pointer items-center gap-3 text-[14px] text-slate-ink">';
    $html .= '<input type="checkbox" class="catalog-filter-grade" value="' . htmlspecialchars($grade['slug']) . '" />';
    $html .= htmlspecialchars($grade['label']) . '</label>';
}
$html .= '</div></div>';

$html .= '<div><h3 class="text-[12px] font-semibold tracking-[0.1em] text-muted uppercase">Сортировка</h3><div class="mt-3.5 flex flex-col gap-2.5">';
$html .= '<label class="flex items-center gap-3 text-[14px]"><input type="radio" name="catalog-sort" value="price-asc" checked /> Сначала дешевле</label>';
$html .= '<label class="flex items-center gap-3 text-[14px]"><input type="radio" name="catalog-sort" value="price-desc" /> Сначала дороже</label>';
$html .= '</div></div>';
$html .= '</div></div></div></div>';

$html .= '<div class="min-w-0 lg:col-span-9">';
$html .= '<div class="mb-5 flex flex-wrap items-center justify-between gap-3">';
$html .= '<p class="text-[13.5px] text-muted">Показано <span id="catalog-count" class="font-semibold text-ink-900">' . count($products) . '</span> позиций</p>';
$html .= '<p class="text-[13.5px] text-muted">Цена от <span class="font-semibold text-ink-900">' . Andromedda::formatPrice($minPrice) . '</span></p>';
$html .= '</div>';

$html .= '<div id="catalog-grid" class="stagger-children grid grid-cols-1 gap-5 sm:grid-cols-2 xl:grid-cols-3">';

foreach ($products as $product) {
    $resource = $modx->getObject('modResource', ['alias' => $product['slug'], 'published' => 1]);
    $url = $resource ? $modx->makeUrl($resource->get('id')) : '/catalog/' . $product['slug'] . '/';
    $dims = Andromedda::formatDimensions($product['length'], $product['width'], $product['height']);

    $html .= '<article class="catalog-card reveal-child min-w-0" data-category="' . htmlspecialchars($product['categorySlug']) . '" data-grade="' . htmlspecialchars($product['gradeSlug']) . '" data-price="' . (int)$product['priceFrom'] . '">';
    $html .= '<a href="' . htmlspecialchars($url) . '" class="group flex h-full min-w-0 flex-col overflow-hidden rounded-[var(--radius-card)] border border-paper-200 bg-paper-0 transition-[border-color,box-shadow,transform] duration-500 hover:-translate-y-1.5 hover:border-clay-300">';
    $html .= '<div class="relative aspect-[4/3] w-full shrink-0 overflow-hidden bg-paper-100">';
    $html .= '<img src="/assets/' . htmlspecialchars($product['imageUrl']) . '" alt="' . htmlspecialchars($product['name']) . '" class="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105" loading="lazy" />';
    $html .= '<span class="absolute top-3 right-3 rounded-md border border-paper-200/80 bg-paper-0/85 px-2 py-1 text-[11px] font-bold">' . htmlspecialchars($product['sku']) . '</span>';
    if ($product['condition'] === 'NEW') {
        $html .= '<span class="absolute top-3 left-3 rounded-md bg-ink-900/90 px-2 py-1 text-[10.5px] font-semibold uppercase text-paper-0">Новые</span>';
    }
    $html .= '</div><div class="flex min-w-0 flex-1 flex-col p-5">';
    $html .= '<h3 class="text-[16px] font-bold text-ink-900 group-hover:text-clay-600">' . htmlspecialchars($product['name']) . '</h3>';
    $html .= '<p class="mt-3 text-[13px] text-muted">' . htmlspecialchars($dims) . ' · ' . htmlspecialchars($product['standard']) . '</p>';
    $html .= '<div class="mt-auto flex items-end justify-between gap-3 pt-6">';
    $html .= '<div><span class="block text-[11px] text-muted">Цена от</span><span class="font-display text-[22px] font-extrabold">' . Andromedda::formatPrice((int)$product['priceFrom']) . '</span></div>';
    $html .= '<span class="inline-flex size-10 items-center justify-center rounded-full border border-paper-200">→</span>';
    $html .= '</div></div></a></article>';
}

$html .= '</div></div></div>';

return $html;

